export const TEXT = Object.fromEntries(['en', 'bn', 'hi'].map(lang => [
  lang, Object.fromEntries(Object.entries(rows).map(([key, value]) => [key, value[lang]])),
]));

export function t(lang, key, vars = {}) {
  const phrase = TEXT[lang]?.[key] ?? TEXT.en[key] ?? key;
  return phrase.replace(/\{([a-zA-Z][a-zA-Z0-9_]*)\}/g, (match, name) => (
    Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match
  ));
}
